--- a/viper.go
+++ b/viper.go
@@ -479,6 +479,8 @@ func (v *Viper) Get(key string) interface{} {
                                val = cast.ToInt(flag.ValueString())
                        case "bool":
                                val = cast.ToBool(flag.ValueString())
+                       case "stringSlice":
+                               val = []string{}
                        default:
                                val = flag.ValueString()
                        }
@@ -742,6 +744,8 @@ func (v *Viper) find(key string) interface{} {
